mapper.sql:
WHERE p.deleted=0 AND r.status=#{status}
AND p.status='PENDING' AND p.round_no=r.round_no AND EXISTS(SELECT 1 FROM approval_step n JOIN approval_assignee a ON a.step_id=n.id WHERE n.id=p.current_step_id AND n.round_no=r.round_no AND a.user_id=#{userId} AND a.status='PENDING' AND n.status='PENDING')
AND EXISTS(SELECT 1 FROM approval_step n JOIN approval_assignee a ON a.step_id=n.id WHERE n.project_id=p.id AND n.round_no=r.round_no AND n.started_at IS NOT NULL AND a.user_id=#{userId} AND a.status IN ('PASSED','REJECTED','CLOSED','CANCELLED'))
